p.m:
\displaystyle{\begin{aligned}
   45\div \frac{9}{4} 
       \amp = \frac{45}{1} \div \frac{9}{4} \\
       \amp = \frac{45}{1} \cdot \frac{4}{9} \amp \hbox{We can divide 45 and 9 by 9 and made those two values smaller.}\\
       \amp = \frac{5}{1}\cdot\frac{4}{1} \\
       \amp = \frac{5\cdot4}{1 \cdot 1} \\
       \amp = 20
\end{aligned}
    }
